// ai_gemm.cu -- naive hand-written GEMM CUDA kernel, standalone program.
//
// Generated by ZCode/GLM (episode 30 AI drafting) from prompts/prompt-gemm.md.
// No post-generation edits are allowed (experiment protocol).
//
// C[M,N] = A[M,K] * B[K,N], row-major, shared-memory tiled kernel.
// fp32 and fp16 (fp16 io + fp32 accumulation).

#include <cuda_runtime.h>
#include <cuda_fp16.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <cmath>
#include <string>
#include <vector>

namespace {

constexpr int kTile = 16;  // block covers a 16x16 output tile (256 threads)

// ---------------------------------------------------------------------------
// Kernels
// ---------------------------------------------------------------------------

template <int TILE>
__global__ void GemmF32Kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int row = blockIdx.y * TILE + threadIdx.y;
    const int col = blockIdx.x * TILE + threadIdx.x;
    float acc = 0.0f;

    const int num_tiles = (K + TILE - 1) / TILE;
    for (int t = 0; t < num_tiles; ++t) {
        const int a_row = blockIdx.y * TILE + threadIdx.y;
        const int a_col = t * TILE + threadIdx.x;
        As[threadIdx.y][threadIdx.x] =
            (a_row < M && a_col < K) ? A[static_cast<size_t>(a_row) * K + a_col] : 0.0f;

        const int b_row = t * TILE + threadIdx.y;
        Bs[threadIdx.y][threadIdx.x] =
            (b_row < K && col < N) ? B[static_cast<size_t>(b_row) * N + col] : 0.0f;

        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < TILE; ++kk) {
            acc += As[threadIdx.y][kk] * Bs[kk][threadIdx.x];
        }
        __syncthreads();
    }

    if (row < M && col < N) {
        C[static_cast<size_t>(row) * N + col] = acc;
    }
}

template <int TILE>
__global__ void GemmF16Kernel(const __half* __restrict__ A,
                              const __half* __restrict__ B,
                              __half* __restrict__ C,
                              int M, int K, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int row = blockIdx.y * TILE + threadIdx.y;
    const int col = blockIdx.x * TILE + threadIdx.x;
    float acc = 0.0f;

    const int num_tiles = (K + TILE - 1) / TILE;
    for (int t = 0; t < num_tiles; ++t) {
        const int a_row = blockIdx.y * TILE + threadIdx.y;
        const int a_col = t * TILE + threadIdx.x;
        As[threadIdx.y][threadIdx.x] =
            (a_row < M && a_col < K)
                ? __half2float(A[static_cast<size_t>(a_row) * K + a_col])
                : 0.0f;

        const int b_row = t * TILE + threadIdx.y;
        Bs[threadIdx.y][threadIdx.x] =
            (b_row < K && col < N)
                ? __half2float(B[static_cast<size_t>(b_row) * N + col])
                : 0.0f;

        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < TILE; ++kk) {
            acc += As[threadIdx.y][kk] * Bs[kk][threadIdx.x];
        }
        __syncthreads();
    }

    if (row < M && col < N) {
        C[static_cast<size_t>(row) * N + col] = __float2half(acc);
    }
}

// ---------------------------------------------------------------------------
// Device runner shared by --run and --bench
// ---------------------------------------------------------------------------

cudaError_t LaunchGemm(const void* A, const void* B, void* C,
                       int M, int K, int N, bool use_fp16) {
    if (M == 0 || N == 0) return cudaSuccess;
    dim3 block(kTile, kTile);
    dim3 grid((N + kTile - 1) / kTile, (M + kTile - 1) / kTile);
    if (use_fp16) {
        GemmF16Kernel<kTile><<<grid, block>>>(
            static_cast<const __half*>(A), static_cast<const __half*>(B),
            static_cast<__half*>(C), M, K, N);
    } else {
        GemmF32Kernel<kTile><<<grid, block>>>(
            static_cast<const float*>(A), static_cast<const float*>(B),
            static_cast<float*>(C), M, K, N);
    }
    return cudaGetLastError();
}

// ---------------------------------------------------------------------------
// Host-side CPU reference (selftest only)
// ---------------------------------------------------------------------------

void CpuGemmF32(const std::vector<float>& A, const std::vector<float>& B,
                int M, int K, int N, std::vector<float>& C) {
    C.assign(static_cast<size_t>(M) * N, 0.0f);
    for (int m = 0; m < M; ++m) {
        for (int n = 0; n < N; ++n) {
            float acc = 0.0f;
            for (int k = 0; k < K; ++k) {
                acc += A[static_cast<size_t>(m) * K + k] *
                       B[static_cast<size_t>(k) * N + n];
            }
            C[static_cast<size_t>(m) * N + n] = acc;
        }
    }
}

void CpuGemmF16(const std::vector<float>& A_f, const std::vector<float>& B_f,
                int M, int K, int N, std::vector<__half>& C) {
    std::vector<__half> A(A_f.size()), B(B_f.size());
    for (size_t i = 0; i < A_f.size(); ++i) A[i] = __float2half(A_f[i]);
    for (size_t i = 0; i < B_f.size(); ++i) B[i] = __float2half(B_f[i]);
    C.assign(static_cast<size_t>(M) * N, __float2half(0.0f));
    for (int m = 0; m < M; ++m) {
        for (int n = 0; n < N; ++n) {
            float acc = 0.0f;
            for (int k = 0; k < K; ++k) {
                acc += __half2float(A[static_cast<size_t>(m) * K + k]) *
                       __half2float(B[static_cast<size_t>(k) * N + n]);
            }
            C[static_cast<size_t>(m) * N + n] = __float2half(acc);
        }
    }
}

int CountMismatchesF32(const std::vector<float>& a, const std::vector<float>& b,
                       float tol) {
    int bad = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        if (std::fabs(a[i] - b[i]) > tol || std::isnan(a[i]) != std::isnan(b[i])) ++bad;
    }
    return bad;
}

int CountMismatchesF16(const std::vector<__half>& a, const std::vector<__half>& b,
                       float tol) {
    int bad = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        const float fa = __half2float(a[i]);
        const float fb = __half2float(b[i]);
        if (std::fabs(fa - fb) > tol || std::isnan(fa) != std::isnan(fb)) ++bad;
    }
    return bad;
}

// ---------------------------------------------------------------------------
// File IO
// ---------------------------------------------------------------------------

bool ReadBinFile(const std::string& path, size_t expected_elems, size_t elem_size,
                 std::vector<uint8_t>& out) {
    FILE* f = std::fopen(path.c_str(), "rb");
    if (!f) {
        std::fprintf(stderr, "[ai_gemm] cannot open file '%s'\n", path.c_str());
        return false;
    }
    std::fseek(f, 0, SEEK_END);
    const long bytes = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (bytes < 0 || static_cast<size_t>(bytes) != expected_elems * elem_size) {
        std::fprintf(stderr,
                     "[ai_gemm] file '%s' size mismatch: got %ld bytes, "
                     "expected %zu (%zu elems x %zu B)\n",
                     path.c_str(), bytes, expected_elems * elem_size,
                     expected_elems, elem_size);
        std::fclose(f);
        return false;
    }
    out.resize(static_cast<size_t>(bytes));
    const size_t got = std::fread(out.data(), 1, out.size(), f);
    std::fclose(f);
    if (got != out.size()) {
        std::fprintf(stderr, "[ai_gemm] short read on '%s'\n", path.c_str());
        return false;
    }
    return true;
}

bool WriteBinFile(const std::string& path, const void* data, size_t bytes) {
    FILE* f = std::fopen(path.c_str(), "wb");
    if (!f) {
        std::fprintf(stderr, "[ai_gemm] cannot open output file '%s'\n", path.c_str());
        return false;
    }
    if (bytes != 0) {
        if (std::fwrite(data, 1, bytes, f) != bytes) {
            std::fprintf(stderr, "[ai_gemm] short write on '%s'\n", path.c_str());
            std::fclose(f);
            return false;
        }
    }
    std::fclose(f);
    return true;
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

struct Args {
    std::string mode;
    long m = -1, k = -1, n = -1;
    std::string dtype;
    std::string a_path, b_path, out_path;
    long warmup = -1, repeats = -1;
};

bool ParseArgs(int argc, char** argv, Args& a) {
    for (int i = 1; i < argc; ++i) {
        const std::string tok = argv[i];
        auto next_string = [&](std::string& dst) -> bool {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "[ai_gemm] missing value for %s\n", tok.c_str());
                return false;
            }
            dst = argv[++i];
            return true;
        };
        auto next_long = [&](long& dst) -> bool {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "[ai_gemm] missing value for %s\n", tok.c_str());
                return false;
            }
            dst = std::strtol(argv[++i], nullptr, 10);
            return true;
        };
        if (tok == "--selftest") a.mode = "selftest";
        else if (tok == "--run") a.mode = "run";
        else if (tok == "--bench") a.mode = "bench";
        else if (tok == "--m") { if (!next_long(a.m)) return false; }
        else if (tok == "--k") { if (!next_long(a.k)) return false; }
        else if (tok == "--n") { if (!next_long(a.n)) return false; }
        else if (tok == "--dtype") { if (!next_string(a.dtype)) return false; }
        else if (tok == "--a") { if (!next_string(a.a_path)) return false; }
        else if (tok == "--b") { if (!next_string(a.b_path)) return false; }
        else if (tok == "--out") { if (!next_string(a.out_path)) return false; }
        else if (tok == "--warmup") { if (!next_long(a.warmup)) return false; }
        else if (tok == "--repeats") { if (!next_long(a.repeats)) return false; }
        else {
            std::fprintf(stderr, "[ai_gemm] unknown argument '%s'\n", tok.c_str());
            return false;
        }
    }
    if (a.mode.empty()) {
        std::fprintf(stderr,
                     "usage: ai_gemm --selftest\n"
                     "       ai_gemm --run --m M --k K --n N --dtype fp32|fp16 "
                     "--a a.bin --b b.bin --out c.bin\n"
                     "       ai_gemm --bench --m M --k K --n N --dtype fp32|fp16 "
                     "--warmup W --repeats N\n");
        return false;
    }
    return true;
}

int RunMode(const Args& a) {
    if (a.m < 0 || a.k < 0 || a.n < 0) {
        std::fprintf(stderr, "[ai_gemm] --run requires --m, --k and --n\n");
        return 2;
    }
    if (a.dtype != "fp32" && a.dtype != "fp16") {
        std::fprintf(stderr, "[ai_gemm] unsupported dtype '%s'\n", a.dtype.c_str());
        return 2;
    }
    if (a.k == 0) {
        std::fprintf(stderr, "[ai_gemm] invalid shape: k = 0\n");
        return 2;
    }
    const bool fp16 = (a.dtype == "fp16");
    const size_t elem_size = fp16 ? 2 : 4;
    const int M = static_cast<int>(a.m);
    const int K = static_cast<int>(a.k);
    const int N = static_cast<int>(a.n);

    if (M == 0 || N == 0) {
        if (!WriteBinFile(a.out_path, nullptr, 0)) return 1;
        return 0;
    }

    std::vector<uint8_t> a_bytes, b_bytes;
    if (!ReadBinFile(a.a_path, static_cast<size_t>(M) * K, elem_size, a_bytes)) return 2;
    if (!ReadBinFile(a.b_path, static_cast<size_t>(K) * N, elem_size, b_bytes)) return 2;

    void *d_a = nullptr, *d_b = nullptr, *d_c = nullptr;
    const size_t a_bytes_n = static_cast<size_t>(M) * K * elem_size;
    const size_t b_bytes_n = static_cast<size_t>(K) * N * elem_size;
    const size_t c_bytes_n = static_cast<size_t>(M) * N * elem_size;
    if (cudaMalloc(&d_a, a_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_b, b_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_c, c_bytes_n) != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] cudaMalloc failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    if (cudaMemcpy(d_a, a_bytes.data(), a_bytes_n, cudaMemcpyHostToDevice) != cudaSuccess ||
        cudaMemcpy(d_b, b_bytes.data(), b_bytes_n, cudaMemcpyHostToDevice) != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] cudaMemcpy H2D failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    const cudaError_t launch_err = LaunchGemm(d_a, d_b, d_c, M, K, N, fp16);
    if (launch_err != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] kernel launch failed: %s\n",
                     cudaGetErrorString(launch_err));
        return 1;
    }
    std::vector<uint8_t> c_bytes(c_bytes_n);
    if (cudaMemcpy(c_bytes.data(), d_c, c_bytes_n, cudaMemcpyDeviceToHost) != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] cudaMemcpy D2H failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    if (!WriteBinFile(a.out_path, c_bytes.data(), c_bytes_n)) return 1;
    cudaFree(d_a);
    cudaFree(d_b);
    cudaFree(d_c);
    return 0;
}

int BenchMode(const Args& a) {
    if (a.m < 0 || a.k < 0 || a.n < 0) {
        std::fprintf(stderr, "[ai_gemm] --bench requires --m, --k and --n\n");
        return 2;
    }
    if (a.dtype != "fp32" && a.dtype != "fp16") {
        std::fprintf(stderr, "[ai_gemm] unsupported dtype '%s'\n", a.dtype.c_str());
        return 2;
    }
    if (a.k == 0) {
        std::fprintf(stderr, "[ai_gemm] invalid shape: k = 0\n");
        return 2;
    }
    if (a.warmup < 0 || a.repeats <= 0) {
        std::fprintf(stderr, "[ai_gemm] --bench requires --warmup and --repeats\n");
        return 2;
    }
    const bool fp16 = (a.dtype == "fp16");
    const size_t elem_size = fp16 ? 2 : 4;
    const int M = static_cast<int>(a.m);
    const int K = static_cast<int>(a.k);
    const int N = static_cast<int>(a.n);
    if (M == 0 || N == 0) {
        std::fprintf(stderr, "[ai_gemm] nothing to bench for m or n = 0\n");
        return 2;
    }

    void *d_a = nullptr, *d_b = nullptr, *d_c = nullptr;
    const size_t a_bytes_n = static_cast<size_t>(M) * K * elem_size;
    const size_t b_bytes_n = static_cast<size_t>(K) * N * elem_size;
    const size_t c_bytes_n = static_cast<size_t>(M) * N * elem_size;
    if (cudaMalloc(&d_a, a_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_b, b_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_c, c_bytes_n) != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] cudaMalloc failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    if (cudaMemset(d_a, 0, a_bytes_n) != cudaSuccess ||
        cudaMemset(d_b, 0, b_bytes_n) != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] cudaMemset failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }

    cudaEvent_t ev_start, ev_stop;
    if (cudaEventCreate(&ev_start) != cudaSuccess ||
        cudaEventCreate(&ev_stop) != cudaSuccess) {
        std::fprintf(stderr, "[ai_gemm] cudaEventCreate failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    for (long i = 0; i < a.warmup; ++i) {
        if (LaunchGemm(d_a, d_b, d_c, M, K, N, fp16) != cudaSuccess) {
            std::fprintf(stderr, "[ai_gemm] warmup launch failed: %s\n",
                         cudaGetErrorString(cudaGetLastError()));
            return 1;
        }
    }
    for (long i = 0; i < a.repeats; ++i) {
        cudaEventRecord(ev_start);
        if (LaunchGemm(d_a, d_b, d_c, M, K, N, fp16) != cudaSuccess) {
            std::fprintf(stderr, "[ai_gemm] timed launch failed: %s\n",
                         cudaGetErrorString(cudaGetLastError()));
            return 1;
        }
        cudaEventRecord(ev_stop);
        float ms = 0.0f;
        cudaEventSynchronize(ev_stop);
        cudaEventElapsedTime(&ms, ev_start, ev_stop);
        std::printf("time_ms %.6f\n", ms);
    }
    std::printf("summary warmup=%ld repeats=%ld\n", a.warmup, a.repeats);
    cudaDeviceSynchronize();
    cudaEventDestroy(ev_start);
    cudaEventDestroy(ev_stop);
    cudaFree(d_a);
    cudaFree(d_b);
    cudaFree(d_c);
    return 0;
}

int SelfTest() {
    struct Case { int m, k, n; bool fp16; };
    const Case cases[] = {
        {4, 8, 4, false},   {13, 17, 11, false}, {16, 16, 16, false},
        {17, 31, 33, false},{32, 48, 20, false}, {4, 8, 4, true},
        {13, 17, 11, true}, {17, 31, 33, true},  {32, 48, 20, true},
    };
    unsigned rng = 20261118u;
    auto next_uniform = [&rng](float lo, float hi) {
        rng = rng * 1664525u + 1013904223u;
        return lo + (hi - lo) * (static_cast<float>(rng & 0xffffff) / 16777216.0f);
    };

    for (const Case& c : cases) {
        const size_t an = static_cast<size_t>(c.m) * c.k;
        const size_t bn = static_cast<size_t>(c.k) * c.n;
        const size_t cn = static_cast<size_t>(c.m) * c.n;
        std::vector<float> A(an), B(bn);
        for (size_t i = 0; i < an; ++i) A[i] = next_uniform(-1.0f, 1.0f);
        for (size_t i = 0; i < bn; ++i) B[i] = next_uniform(-1.0f, 1.0f);

        const size_t elem_size = c.fp16 ? 2 : 4;
        void *d_a = nullptr, *d_b = nullptr, *d_c = nullptr;
        if (cudaMalloc(&d_a, an * elem_size) != cudaSuccess ||
            cudaMalloc(&d_b, bn * elem_size) != cudaSuccess ||
            cudaMalloc(&d_c, cn * elem_size) != cudaSuccess) {
            std::fprintf(stderr, "[selftest] cudaMalloc failed: %s\n",
                         cudaGetErrorString(cudaGetLastError()));
            return 1;
        }
        int bad = 0;
        if (c.fp16) {
            std::vector<__half> C_dev, C_ref;
            std::vector<__half> Ah(an), Bh(bn);
            for (size_t i = 0; i < an; ++i) Ah[i] = __float2half(A[i]);
            for (size_t i = 0; i < bn; ++i) Bh[i] = __float2half(B[i]);
            cudaMemcpy(d_a, Ah.data(), an * 2, cudaMemcpyHostToDevice);
            cudaMemcpy(d_b, Bh.data(), bn * 2, cudaMemcpyHostToDevice);
            LaunchGemm(d_a, d_b, d_c, c.m, c.k, c.n, true);
            cudaDeviceSynchronize();
            C_dev.resize(cn);
            cudaMemcpy(C_dev.data(), d_c, cn * 2, cudaMemcpyDeviceToHost);
            CpuGemmF16(A, B, c.m, c.k, c.n, C_ref);
            bad = CountMismatchesF16(C_dev, C_ref, 5e-2f);
        } else {
            std::vector<float> C_dev, C_ref;
            cudaMemcpy(d_a, A.data(), an * 4, cudaMemcpyHostToDevice);
            cudaMemcpy(d_b, B.data(), bn * 4, cudaMemcpyHostToDevice);
            LaunchGemm(d_a, d_b, d_c, c.m, c.k, c.n, false);
            cudaDeviceSynchronize();
            C_dev.resize(cn);
            cudaMemcpy(C_dev.data(), d_c, cn * 4, cudaMemcpyDeviceToHost);
            CpuGemmF32(A, B, c.m, c.k, c.n, C_ref);
            bad = CountMismatchesF32(C_dev, C_ref, 1e-3f);
        }
        std::printf("[selftest] %s m=%d k=%d n=%d mismatches=%d\n",
                    c.fp16 ? "fp16" : "fp32", c.m, c.k, c.n, bad);
        if (bad != 0) {
            std::printf("SELFTEST FAIL\n");
            return 1;
        }
        cudaFree(d_a);
        cudaFree(d_b);
        cudaFree(d_c);
    }
    std::printf("SELFTEST PASS\n");
    return 0;
}

}  // namespace

int main(int argc, char** argv) {
    Args a;
    if (!ParseArgs(argc, argv, a)) return 2;
    if (a.mode == "selftest") return SelfTest();
    if (a.mode == "run") return RunMode(a);
    if (a.mode == "bench") return BenchMode(a);
    return 2;
}
